#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    if (n >= m) {
        cout << n - m << "\n";
        return 0;
    }

    // Upper bound for visited array. 
    // Since we multiply by 2, we don't need to go much beyond 2*m.
    // Adding a small buffer.
    int max_limit = 2 * m + 10;
    vector<bool> visited(max_limit + 1, false);

    queue<int> q;
    q.push(n);
    visited[n] = true;

    int steps = 0;

    while (!q.empty()) {
        int sz = q.size();
        while (sz--) {
            int curr = q.front();
            q.pop();

            if (curr == m) {
                cout << steps << "\n";
                return 0;
            }

            // Operation 1: Multiply by 2
            long long next_mul = 1LL * curr * 2;
            if (next_mul <= max_limit && !visited[next_mul]) {
                visited[next_mul] = true;
                q.push((int)next_mul);
            }

            // Operation 2: Subtract 1
            int next_sub = curr - 1;
            if (next_sub >= 1 && !visited[next_sub]) {
                visited[next_sub] = true;
                q.push(next_sub);
            }
        }
        steps++;
    }

    return 0;
}

